#!/usr/bin/env node
/**
 * catalog.json → src/generated/{catalog,events,props}.ts.
 *
 *   node scripts/gen-catalog.mjs          write the generated files
 *   node scripts/gen-catalog.mjs --check  exit 1 when they are stale
 *
 * catalog.json is the canonical schema of the wire (design §5, §6); the
 * generated TS is what the SDK and app authors compile against. Never edit
 * the generated files by hand: change catalog.json (through the
 * orchestration, with the ide copy) and run this script.
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')

const HEADER = '// Generated by scripts/gen-catalog.mjs from catalog.json. Do not edit.\n'

/**
 * Per-component argument types of an event, where the catalog's generic
 * `args` names are not enough to type a handler (`change` is a bool on a
 * Switch and the text on a TextField; RemoteScreen's longPress carries the
 * page point).
 */
const EVENT_ARGS = {
  change: { Switch: 'checked: boolean', TextField: 'text: string' },
  submit: { '*': 'text: string' },
  select: { '*': 'index: number' },
  focus: { '*': 'focused: boolean' },
  frame: { '*': 'width: number, height: number' },
  error: { '*': 'message: string' },
  keyboard: { '*': 'open: boolean' },
  longPress: { RemoteScreen: 'x: number, y: number' },
}

/** Props an SDK component owns itself instead of passing straight through. */
const HAND_TYPED = {
  TextField: { value: 'string | null' },
  List: { keyField: null, kindField: null },
}

/** The JSX children of these components become their `text` prop. */
const TEXT_CHILDREN = new Set(['Text', 'Badge', 'Button', 'Chip'])

const pascal = (s) => s[0].toUpperCase() + s.slice(1)
const handlerName = (event) => `on${pascal(event)}`
const q = (s) => `'${String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`

function tsValueType(prop) {
  switch (prop.type) {
    case 'bool':
      return 'boolean'
    case 'int':
    case 'float':
    case 'dp':
      return 'number'
    case 'string':
      return 'string'
    case 'icon':
      return 'IconName'
    case 'strings':
      return 'readonly string[]'
    case 'json':
      return 'JsonValue'
    case 'padding':
      return 'Padding'
    case 'enum':
      return pascal(prop.enum)
    default:
      throw new Error(`catalog: no TS type for value type ${prop.type}`)
  }
}

function eventArgs(event, typeName) {
  const byType = EVENT_ARGS[event]
  if (!byType) return ''
  return byType[typeName] ?? byType['*'] ?? ''
}

/** A JSON value as a TS literal in the repo's style (single quotes). */
function literal(value) {
  if (typeof value === 'string') return q(value)
  if (Array.isArray(value)) return `[${value.map(literal).join(', ')}]`
  return JSON.stringify(value ?? null)
}

function propSpec(prop) {
  const enumName = prop.type === 'enum' ? q(prop.enum) : 'null'
  return `[${prop.tag}, ${q(prop.type)}, ${enumName}, ${literal(prop.default ?? null)}]`
}

/** `head[a, b]tail` on one line, or one item per line when it would pass biome's 120 columns. */
function list(head, items, tail, indent = '') {
  const flat = `${indent}${head}${items.join(', ')}${tail}`
  if (flat.length <= 120) return [flat]
  return [`${indent}${head.trimEnd()}`, ...items.map((i) => `${indent}  ${i},`), `${indent}${tail.trimStart()}`]
}

/** `head{ a, b }tail` on one line, or one entry per line when it would pass 120 columns. */
function object(head, entries, tail, indent = '') {
  if (!entries.length) return [`${indent}${head}{}${tail}`]
  const flat = `${indent}${head}{ ${entries.join(', ')} }${tail}`
  if (flat.length <= 120) return [flat]
  return [`${indent}${head}{`, ...entries.map((e) => `${indent}  ${e},`), `${indent}}${tail}`]
}

/** A string-literal union type, one member per line when it would pass 120 columns. */
function union(head, members) {
  const flat = `${head} ${members.join(' | ')}`
  if (flat.length <= 120) return [flat]
  return [head, ...members.map((m) => `  | ${m}`)]
}

function genCatalog(catalog) {
  const out = [HEADER]
  out.push(`export const CATALOG_VERSION = ${catalog.catalogVersion}\n`)
  out.push(...list('export const FEATURES = [', catalog.features.map(q), '] as const'), '')
  out.push('export const LIMITS = {')
  for (const [k, v] of Object.entries(catalog.limits)) out.push(`  ${k}: ${v},`)
  out.push('} as const\n')
  out.push(`export const BINDING_KEY = ${q(catalog.binding.key)}\n`)

  out.push('export const ENUMS = {')
  for (const [name, values] of Object.entries(catalog.enums)) out.push(...list(`${name}: [`, values.map(q), '],', '  '))
  out.push('} as const\n')
  out.push('export type EnumName = keyof typeof ENUMS\n')
  for (const name of Object.keys(catalog.enums)) {
    out.push(`export type ${pascal(name)} = (typeof ENUMS)['${name}'][number]`)
  }
  out.push('')

  const codes = (list, key) => list.map((e) => `  ${e.name}: ${e[key]},`)
  out.push('/** VM → host entry codes (design §5.3). */')
  out.push('export const OP = {', ...codes(catalog.protocol.vmToHost, 'code'), '} as const\n')
  out.push('/** Host → VM entry codes (design §5.6). */')
  out.push('export const IN = {', ...codes(catalog.protocol.hostToVm, 'code'), '} as const\n')
  out.push('/** Request methods (design §5.4). */')
  out.push('export const METHOD = {', ...codes(catalog.protocol.requests, 'method'), '} as const\n')
  out.push(...list('export const ERROR_CODES = [', catalog.protocol.errorCodes.map(q), '] as const'), '')
  out.push('export type ErrorCode = (typeof ERROR_CODES)[number]\n')
  out.push(...list('export const ENV_KEYS = [', Object.keys(catalog.protocol.env).map(q), '] as const'), '')
  out.push(`export const ROOT_PAGE = ${q(catalog.protocol.rootPage)}\n`)

  out.push(...union('export type ValueType =', Object.keys(catalog.valueTypes).map(q)), '')
  out.push('/** [tag, value type, enum name or null, the default]. */')
  out.push('export type PropSpec = readonly [number, ValueType, EnumName | null, unknown]\n')
  out.push('/** [slot index, takes many children, is a List template]. */')
  out.push('export type SlotSpec = readonly [number, boolean, boolean]\n')
  out.push('export interface TypeSpec {')
  out.push('  readonly tag: number')
  out.push('  readonly props: Readonly<Record<string, PropSpec>>')
  out.push('  /** Handler prop name (onPress) → event tag. */')
  out.push('  readonly events: Readonly<Record<string, number>>')
  out.push('  readonly slots: Readonly<Record<string, SlotSpec>>')
  out.push('}\n')

  out.push('/** Props every type has (tags 1–9). */')
  out.push('export const COMMON_PROPS: Readonly<Record<string, PropSpec>> = {')
  for (const p of catalog.commonProps) out.push(`  ${p.name}: ${propSpec(p)},`)
  out.push('}\n')

  out.push('export const TYPES = {')
  for (const t of catalog.types) {
    out.push(`  ${t.name}: {`)
    out.push(`    tag: ${t.tag},`)
    out.push('    props: {')
    for (const p of t.props) out.push(`      ${p.name}: ${propSpec(p)},`)
    out.push('    },')
    const events = t.events.map((e) => `${handlerName(e)}: ${eventTag(catalog, e)}`)
    out.push(...object('events: ', events, ',', '    '))
    const slots = t.slots.map((s) => `${s.name}: [${s.slot}, ${s.many}, ${Boolean(s.template)}]`)
    out.push(...object('slots: ', slots, ',', '    '))
    out.push('  },')
  }
  out.push('} as const satisfies Record<string, TypeSpec>\n')
  out.push('export type TypeName = keyof typeof TYPES')
  return `${out.join('\n')}\n`
}

function eventTag(catalog, name) {
  const e = catalog.events.find((x) => x.name === name)
  if (!e) throw new Error(`catalog: unknown event ${name}`)
  return e.tag
}

function genEvents(catalog) {
  const out = [HEADER]
  out.push('/** Event tags (design §6.1); a node subscribes with bit `1 << tag` of its `events` prop. */')
  out.push('export const EVENTS = {')
  for (const e of catalog.events) out.push(`  ${e.name}: ${e.tag},`)
  out.push('} as const\n')
  out.push('export type EventName = keyof typeof EVENTS\n')
  out.push('/** Handler prop name → event tag. */')
  out.push('export const EVENT_PROPS: Readonly<Record<string, number>> = {')
  for (const e of catalog.events) out.push(`  ${handlerName(e.name)}: ${e.tag},`)
  out.push('}')
  return `${out.join('\n')}\n`
}

function genProps(catalog) {
  const out = [HEADER]
  out.push("import type { JSX } from 'solid-js'")
  out.push("import type { IconName, JsonValue, NodeRef, Padding, Prop } from '../types'")
  const used = new Set(
    [...catalog.commonProps, ...catalog.types.flatMap((t) => t.props)].map((p) => p.enum).filter(Boolean),
  )
  const enums = Object.keys(catalog.enums)
    .filter((name) => used.has(name))
    .map(pascal)
    .sort()
  out.push(...list('import type { ', enums, " } from './catalog'"), '')

  out.push('/** The props every component takes. */')
  out.push('export interface CommonProps {')
  for (const p of catalog.commonProps) {
    if (p.name === 'events') continue
    if (p.doc) out.push(`  /** ${p.doc} */`)
    out.push(`  ${p.name}?: Prop<${tsValueType(p)}>`)
  }
  out.push(
    '  /** The node, as an anchor for `iii.ui.actionMenu` or a target for `iii.ui.focus` (`ref={variable}` assigns it). */',
  )
  out.push('  ref?: NodeRef | ((node: NodeRef) => void)')
  out.push('}\n')

  for (const t of catalog.types) {
    const hand = HAND_TYPED[t.name] ?? {}
    const base = t.name === 'List' ? 'ListBaseProps' : `${t.name}Props`
    out.push(`/** ${t.name} (${t.tag}). */`)
    out.push(`export interface ${base} extends CommonProps {`)
    for (const p of t.props) {
      if (p.name in hand) {
        if (hand[p.name] === null) continue
        if (p.doc) out.push(`  /** ${p.doc} */`)
        out.push(`  ${p.name}?: ${hand[p.name]}`)
        continue
      }
      if (p.doc) out.push(`  /** ${p.doc} */`)
      out.push(`  ${p.name}?: Prop<${tsValueType(p)}>`)
    }
    for (const e of t.events) {
      const args = eventArgs(e, t.name)
      // Inside a List template the item comes first; an argument-less
      // handler takes it as an optional parameter.
      out.push(`  ${handlerName(e)}?: ${args ? `(${args}) => void` : '(item?: any) => void'}`)
    }
    for (const s of t.slots) {
      if (s.template) continue
      out.push(`  ${s.name}?: JSX.Element`)
    }
    const hasChildrenSlot = t.slots.some((s) => s.slot === 0)
    if (TEXT_CHILDREN.has(t.name))
      out.push('  /** Text children become the `text` prop. */', '  children?: JSX.Element')
    else if (hasChildrenSlot && !t.slots.some((s) => s.name === 'children')) {
      const name = t.slots.find((s) => s.slot === 0).name
      out.push(`  /** Slot 0 (\`${name}\`). */`, '  children?: JSX.Element')
    }
    out.push('}\n')
  }
  return `${out.join('\n').trimEnd()}\n`
}

export function generate(catalog = JSON.parse(readFileSync(join(root, 'catalog.json'), 'utf8'))) {
  return {
    'src/generated/catalog.ts': genCatalog(catalog),
    'src/generated/events.ts': genEvents(catalog),
    'src/generated/props.ts': genProps(catalog),
  }
}

/** The generated files whose content on disk differs from catalog.json's. */
export function staleFiles() {
  const stale = []
  for (const [rel, content] of Object.entries(generate())) {
    let current = null
    try {
      current = readFileSync(join(root, rel), 'utf8')
    } catch {}
    if (current !== content) stale.push(rel)
  }
  return stale
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  if (process.argv.includes('--check')) {
    const stale = staleFiles()
    if (stale.length) {
      console.error(`stale generated files (run node scripts/gen-catalog.mjs): ${stale.join(', ')}`)
      process.exit(1)
    }
  } else {
    for (const [rel, content] of Object.entries(generate())) writeFileSync(join(root, rel), content)
  }
}
